const MCCARTHY_91 = {
  answer: 4,
  hint: String.raw`$M(100)$ و $M(101)$ را حساب کن، بعد ببین برای $n$های کوچک‌تر چه می‌شود.`,
  shortcut: String.raw`تابع ۹۱ مک‌کارتی: $M(101)=91$، و برای $90\le n\le100$ داریم $M(n)=M(n+1)=\dots=M(101)=91$؛ برای کوچک‌ترها هم با بالا رفتن به همین بازه می‌رسیم. پس برای همهٔ $n\le101$ مقدار ۹۱ است؛ گزینهٔ ۴.`,
  solution: [
    t(String.raw`$M(101)=91$ مستقیم از تعریف. برای $90\le n\le100$: $M(n)=M(M(n+11))=M(n+1)$، چون $n+11>100$ و $M(n+11)=n+1$. پس $M(90)=M(91)=\dots=M(101)=91$.`),
    t(String.raw`برای $n<90$: $M(n)=M(M(n+11))$. با استقرای قوی از بالا به پایین، $M(n+11)=91$ (چون $n+11\le101$)، پس $M(n)=M(91)=91$.`),
    t(String.raw`نتیجه: برای هر $n\le101$، $M(n)=91$ و تابع همیشه پایان می‌یابد؛ گزینهٔ ۴. گزینهٔ ۲ هم درست است ولی بخشی از همین حکم است؛ گزینه‌های ۱ و ۳ نادرست‌اند.`),
  ],
};

