  "kunkurcomputer-q-1209-1388-D-081": {
    answer: 3,
    hint: "اگر اعداد مرتب بودند، با دو اشاره‌گر از دو سر آرایه چه می‌کردی؟",
    shortcut: String.raw`مرتب کن ($O(n\lg n)$)، بعد دو اشاره‌گر از دو سر: اگر جمع کمتر از $x$ بود چپ را جلو ببر، اگر بیشتر بود راست را عقب؛ $O(n)$. کل: $O(n\lg n)$؛ گزینهٔ ۳.`,
    solution: [
      t(String.raw`روش ساده بررسی همهٔ جفت‌هاست: $\binom n2$ جفت، یعنی $O(n^2)$ (گزینهٔ ۲). می‌شود بهتر عمل کرد.`),
      t(String.raw`اعداد را با یک مرتب‌سازی مقایسه‌ای در $O(n\lg n)$ مرتب می‌کنیم. اشاره‌گر $i$ را روی کوچک‌ترین و $j$ را روی بزرگ‌ترین می‌گذاریم: اگر $a_i+a_j=x$ پیدا کرده‌ایم؛ اگر کمتر است $i$ را یکی جلو می‌بریم (هیچ عددی با $a_i$ به $x$ نمی‌رسد)؛ اگر بیشتر است $j$ را عقب می‌آوریم. هر قدم یک اشاره‌گر را حرکت می‌دهد، پس این بخش $O(n)$ است.`),
      t(String.raw`زمان کل $O(n\lg n)$ است؛ گزینهٔ ۳. (به‌جای دو اشاره‌گر می‌شود برای هر $a_i$ عدد $x-a_i$ را با جست‌وجوی دودویی پیدا کرد؛ باز هم $O(n\lg n)$.)`),
      t(String.raw`نکته: با جدول درهم‌سازی زمان «میانگین» $O(n)$ می‌شود، ولی بدترین حالت آن تضمین ندارد؛ پاسخ استاندارد در مدل مقایسه‌ای همان $O(n\lg n)$ است.`),
    ],
  },
  "kunkurcomputer-q-1209-1388-D-083": {
    answer: 2,
    hint: String.raw`چهار تابع را مرتب کن: توانی از $\lg n$، توان کوچکی از $n$، $\sqrt n$ و $\lg n!$.`,
    shortcut: String.raw`ترتیب رشد: $(\lg n)^k\ll n^\varepsilon\le\sqrt n\ll n\lg n=\lg n!$. فقط گزینهٔ ۲ همین ترتیب را دارد.`,
    solution: [
      t(String.raw`هر توان ثابتی از $\lg n$ از هر توان مثبتی از $n$ کندتر رشد می‌کند: $(\lg n)^k=O(n^\varepsilon)$ برای هر $\varepsilon>0$.`),
      t(String.raw`$\lg n!=\Theta(n\lg n)$ (تقریب استرلینگ) که از $\sqrt n$ بسیار سریع‌تر است؛ پس $\sqrt n=O(\lg n!)$ ولی نه برعکس. همین گزینهٔ ۳ را رد می‌کند (که $\lg n!=O(\sqrt n)$ ادعا می‌کند).`),
      t(String.raw`گزینه‌های ۱ و ۴ ادعا می‌کنند $\sqrt n$ یا $n^\varepsilon$ در $O((\lg n)^k)$ است؛ هر دو نادرست‌اند.`),
      t(String.raw`گزینهٔ ۲ ترتیب درست را دارد. یک ریزه‌کاری: حلقهٔ $n^\varepsilon=O(\sqrt n)$ فقط برای $0<\varepsilon\le\frac12$ برقرار است، نه برای هر $\varepsilon<1$؛ طراح $\varepsilon$ را عدد کوچکی در نظر گرفته است. با این حال گزینهٔ ۲ تنها گزینه‌ای است که ترتیب کلی را درست می‌گوید.`),
    ],
  },
  "kunkurcomputer-q-1209-1393-370E-171": {
    answer: 1,
    hint: "در یک لیست مرتب، نزدیک‌ترین دو عدد کجا قرار می‌گیرند؟",
    shortcut: String.raw`مرتب کن و فقط عددهای مجاور را مقایسه کن: $O(n\log n)+O(n)$؛ گزینهٔ ۱. کمتر هم نمی‌شود، چون این مسئله «تکراری نبودن عناصر» را هم حل می‌کند.`,
    solution: [
      t(String.raw`بعد از مرتب‌سازی، جفتی که کمترین اختلاف را دارد حتماً دو عدد مجاور است: اگر $a<b<c$ باشد، $c-a$ از $b-a$ بیشتر است. پس با یک پیمایش روی $n-1$ جفت مجاور جواب پیدا می‌شود.`),
      t(String.raw`زمان کل: مرتب‌سازی $O(n\log n)$ و پیمایش $O(n)$، یعنی $O(n\log n)$.`),
      t(String.raw`چرا بهتر نمی‌شود: اگر کمترین اختلاف را داشته باشیم، می‌فهمیم آیا دو عدد برابر وجود دارد یا نه (کمترین اختلاف صفر است یا نه). مسئلهٔ «یکتایی عناصر» در مدل مقایسه‌ای کران پایین $\Omega(n\log n)$ دارد؛ پس این مسئله هم دارد. جواب: گزینهٔ ۱.`),
    ],
  },
  "kunkurcomputer-q-1209-1394-371F-103": GROWTH_LOG_FACTORIAL,
  "kunkurcomputer-q-1209-1394-371F-193": GROWTH_LOG_FACTORIAL,
