  "kunkurcomputer-q-1209-1384-b0-092": {
    answer: 4,
    hint: "ترتیب max-heap به ساختن min-heap کمکی نمی‌کند؛ ساختن هرم از یک آرایهٔ دلخواه چند مقایسه می‌خواهد؟",
    shortcut: String.raw`آرایه را یک آرایهٔ دلخواه بگیر و با Build-Heap از پایین به بالا min-heap بساز: حداکثر حدود $2n$ مقایسه، یعنی $O(n)$؛ گزینهٔ ۴.`,
    solution: [
      t(String.raw`max-heap یک آرایه است و الگوریتم Build-Heap (فلوید) هر آرایهٔ دلخواهی را در زمان خطی به هرم تبدیل می‌کند: از آخرین گره داخلی به سمت ریشه، هر گره را با Heapify پایین می‌بریم.`),
      t(String.raw`گرهی به ارتفاع $h$ در Heapify حداکثر $2h$ مقایسه می‌کند (در هر سطح: مقایسهٔ دو فرزند با هم و بعد با خود گره). حداکثر $\lceil\frac n{2^{h+1}}\rceil$ گره ارتفاع $h$ دارند، پس کل مقایسه‌ها $\sum_h\frac n{2^{h+1}}\cdot2h=n\sum_h\frac h{2^h}\le2n$ است.`),
      t(String.raw`جواب $O(2n)$ یعنی $O(n)$؛ گزینهٔ ۴. گزینهٔ ۳ زمان درج یکی‌یکی $n$ عنصر است که لازم نیست. گزینهٔ ۱ هم از نظر مرتبه برابر $O(n)$ است ولی کلید گزینهٔ ۴ را که دقیقاً کران مقایسه‌های Build-Heap است انتخاب کرده.`),
    ],
  },
