    shortcut: String.raw`گره‌های داخلی ۱ تا ۶ هستند. هر سطح پایین رفتن ۲ مقایسه است (۱ اگر فقط یک فرزند باشد): گرهٔ ۶: ۱، گره‌های ۵ و ۴: ۲ و ۲، گرهٔ ۳: ۳، گرهٔ ۲: ۴، ریشه: ۶. جمع ۱۸؛ گزینهٔ ۴.`,
