  "kunkurcomputer-q-1209-1388-D-087": {
    answer: 1,
    hint: "دنباله را به شکل درخت بچین (فرزندان خانهٔ i در 2i و 2i+1) و جاهایی را که فرزند از پدر بزرگ‌تر است پیدا کن.",
    shortcut: "دو خطا هست: ۶ (با فرزندان ۵ و ۷) و ۳ (با فرزند ۱۱). عدد جایگزین باید از فرزندان بزرگ‌تر و از پدرش ۱۷ کوچک‌تر باشد: ۱۲ و ۱۵ هر دو کار می‌کنند؛ گزینهٔ ۱.",
    solution: [
      t(String.raw`با شماره‌گذاری از ۱: خانهٔ ۲ (۱۷) فرزندان ۶ و ۳ را دارد، خانهٔ ۴ (۶) فرزندان ۵ و ۷، و خانهٔ ۵ (۳) فرزند ۱۱. پس دو جا شرط max-heap نقض شده: ۷ > ۶ و ۱۱ > ۳.`),
      t(String.raw`مقدار جدید خانهٔ ۴ باید دست‌کم ۷ و حداکثر ۱۷ باشد، و خانهٔ ۵ دست‌کم ۱۱ و حداکثر ۱۷. گزینهٔ ۱ (۶→۱۲ و ۳→۱۵) هر دو شرط را دارد.`),
      t(String.raw`گزینهٔ ۲ ۷ را به ۸ می‌برد که باز از ۶ بزرگ‌تر است؛ گزینهٔ ۳ ۳ را به ۱۰ می‌برد که از فرزندش ۱۱ کوچک‌تر است؛ گزینهٔ ۴ به هیچ‌کدام از دو خطا دست نمی‌زند. جواب: گزینهٔ ۱.`),
    ],
  },
  "kunkurcomputer-q-1209-1390-372B-091": {
    answer: 1,
    hint: "کوچک‌ترین عنصر در هرم ماکزیمم کجاست و چطور پیدایش می‌کنیم؟",
    shortcut: String.raw`از هرم مینیمم در $O(\log n)$ حذف می‌شود، ولی همان عنصر باید از هرم ماکزیمم هم حذف شود؛ آنجا جایی بین $\frac n2$ برگ است و پیدا کردنش $O(n)$ است؛ گزینهٔ ۱.`,
    solution: [
      t(String.raw`حذف از هرم مینیمم ساده است: ریشه را برمی‌داریم و با Heapify درست می‌کنیم؛ $O(\log n)$.`),
      t(String.raw`اما داده باید از هرم ماکزیمم هم حذف شود. در هرم ماکزیمم، کوچک‌ترین عنصر حتماً یک برگ است، ولی هر کدام از حدود $\frac n2$ برگ ممکن است باشد و ترتیب هرم کمکی برای پیدا کردنش نمی‌کند؛ جست‌وجو $O(n)$ است. بعد از پیدا کردن، حذفش $O(\log n)$ است.`),
      t(String.raw`زمان کل $O(n)$؛ گزینهٔ ۱. اگر دو هرم با اشاره‌گر به هم وصل بودند (هر عنصر جای خودش در هرم دیگر را بداند)، $O(\log n)$ ممکن می‌شد؛ ساختارهایی مثل deap و min-max heap برای همین ساخته شده‌اند.`),
    ],
  },
