    shortcut: String.raw`هر گره دقیقاً $a$ فرزند دارد تا اندازه به ۱ برسد: درخت کامل $a$تایی با عمق $\log_bn$ و $a^{\log_bn}=n^{\log_ba}$ برگ؛ گزینهٔ ۲.`,
