    shortcut: String.raw`I: $L-F=L\cap\overline F$ منظم است. II: اگر $L\cup F$ منظم بود، $L=(L\cup F)-(F-L)$ هم منظم می‌شد؛ تناقض. هر دو درست؛ گزینهٔ ۳.`,
