    shortcut: "حالت‌ها: شروع؛ قبل از ۱۱ با آخر ۰؛ قبل از ۱۱ با آخر ۱؛ بعد از ۱۱ با آخر ۱ (پذیرش)؛ بعد از ۱۱ با آخر ۰ (پذیرش). ۵ حالت با ۲ پذیرش، بدون شمردن حالت مرده (برای ۰۰)؛ گزینهٔ ۱.",
